// Only exact pure maintenance bytes can stop traversal into server-side Debian access.
// Direct Debian access imports and any source/import drift retain ordinary denial.
func phase10DependencyPruning(packages []listedPackage, module string) map[string]bool {
	pruned := map[string]bool{}
	for _, candidate := range packages {
		if candidate.ImportPath == module+"/internal/maintenance" && approvedNetworkConnectPackage(checkedSourcePackage{listed: candidate}, module, "internal/maintenance") {
			pruned[candidate.ImportPath] = true
		}
	}
	return pruned
}
